# Operation base
# ---------------------------------------------------------------------------


class HWOp(Operation):
    """Shared behaviour for hardware operations.

    Hardware operations can be built two ways:

    * from the parser, where operands are real SSA :class:`Value` objects, or
    * *behaviourally*, by passing operand **names** as strings.

    ``read_operand`` hides the difference so simulators and folders work with
    either representation.
    """

    OPERATION_NAME: Optional[str] = None

    #: Set when the operation was built from signal names rather than SSA values.
    _symbolic_operands: Optional[List[str]] = None
    #: Declared result width (used when there is no result type to read).
    _declared_width: int = 0
    #: Preferred name for the result, mirroring CIRCT's ``result_name``.
    result_name: str = ""

    def __init__(
        self,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        result_types: Optional[Sequence[Type]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        width: int = 0,
        result_name: str = "",
        name: Optional[str] = None,
        location: Optional[Location] = None,
        successors: Optional[Sequence[Block]] = None,
        regions: Optional[Sequence[Region]] = None,
    ) -> None:
        raw = list(operands or ())
        symbolic = [item for item in raw if isinstance(item, str)]
        values = [item for item in raw if isinstance(item, Value)]
        if symbolic and values:
            raise ValueError("cannot mix SSA values and signal names in one operation")

        types = list(result_types or ())
        if not types and width:
            types = [IntType(width)] * self.default_num_results()

        super().__init__(
            name=name or self.operation_name(),
            operands=values,
            result_types=types,
            attributes=attributes,
            successors=successors,
            regions=regions,
            location=location,
            result_names=[result_name] if result_name else None,
        )
        self._symbolic_operands = symbolic or None
        self._declared_width = int(width)
        self.result_name = result_name

    # -- construction helpers ---------------------------------------------
    @classmethod
    def default_num_results(cls) -> int:
        return 1

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> "Operation":
        op = cls.__new__(cls)
        Operation.__init__(op, **kwargs)
        op._symbolic_operands = None
        op._declared_width = 0
        results = kwargs.get("result_names") or []
        op.result_name = next((r for r in results if r), "")
        return op

    # -- operand access ---------------------------------------------------
    @property
    def operands(self) -> List[Any]:
        """SSA values, or signal names when built behaviourally."""
        if self._symbolic_operands is not None:
            return list(self._symbolic_operands)
        return Operation.operands.fget(self)  # type: ignore[attr-defined]

    @property
    def ssa_operands(self) -> List[Value]:
        return Operation.operands.fget(self)  # type: ignore[attr-defined]

    @property
    def operand_names(self) -> List[str]:
        if self._symbolic_operands is not None:
            return list(self._symbolic_operands)
        return [v.name or f"%{index}" for index, v in enumerate(self.ssa_operands)]

    @property
    def num_operands(self) -> int:
        if self._symbolic_operands is not None:
            return len(self._symbolic_operands)
        return Operation.num_operands.fget(self)  # type: ignore[attr-defined]

    def get_operand(self, index: int) -> Any:
        operands = self.operands
        if index < 0 or index >= len(operands):
            raise IndexError(f"operand index {index} out of range")
        return operands[index]

    def read_operand(self, env: SignalEnv, index: int, default: int = 0) -> int:
        """Read operand ``index`` out of ``env``."""
        if self._symbolic_operands is not None:
            if index >= len(self._symbolic_operands):
                return default
            key = self._symbolic_operands[index]
            return int(env.get(key, default))
        values = self.ssa_operands
        if index >= len(values):
            return default
        value = values[index]
        if value in env:
            return int(env[value])
        if value.name is not None and value.name in env:
            return int(env[value.name])
        return default

    def read_operands(self, env: SignalEnv) -> List[int]:
        return [self.read_operand(env, i) for i in range(self.num_operands)]

    # -- widths -----------------------------------------------------------
    @property
    def width(self) -> int:
        if self.num_results:
            return bit_width_of(Operation.results.fget(self)[0].type)  # type: ignore[attr-defined]
        return self._declared_width

    def infer_width(self, type_env: Optional[Dict[str, int]] = None) -> int:
        return self.width

    def mask(self) -> int:
        width = self.width
        return (1 << width) - 1 if width > 0 else 0

    def truncate(self, value: int) -> int:
        mask = self.mask()
        return value & mask if mask else int(value)

    # -- evaluation -------------------------------------------------------
    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        raise NotImplementedError(f"{self.name} does not implement evaluate()")

    def fold(self) -> Optional[List[Any]]:
        """Constant-fold using the operands' ``hw.constant`` definitions."""
        if self._symbolic_operands is not None or not self.num_results:
            return None
        env: SignalEnv = {}
        for value in self.ssa_operands:
            defining = value.defining_op
            if defining is None or not isinstance(defining, ConstantOp):
                return None
            env[value] = defining.evaluate()
        try:
            return [self.evaluate(env)]
        except (NotImplementedError, ZeroDivisionError):
            return None


