class Region:
    """An ordered list of blocks owned by an operation."""

    def __init__(self, blocks: Optional[Sequence[Block]] = None) -> None:
        self.parent: Optional[Operation] = None
        self.blocks: List[Block] = []
        for block in blocks or ():
            self.add_block(block)

    def add_block(self, block: Optional[Block] = None) -> Block:
        block = block if block is not None else Block()
        block.parent = self
        self.blocks.append(block)
        return block

    def insert_block(self, index: int, block: Block) -> Block:
        block.parent = self
        self.blocks.insert(index, block)
        return block

    @property
    def entry_block(self) -> Optional[Block]:
        return self.blocks[0] if self.blocks else None

    @property
    def num_blocks(self) -> int:
        return len(self.blocks)

    def block(self, index: int = 0) -> Block:
        return self.blocks[index]

    def find_block(self, label: str) -> Optional[Block]:
        for block in self.blocks:
            if block.label == label:
                return block
        return None

    def erase_all_blocks(self) -> None:
        for block in reversed(list(self.blocks)):
            block.erase_all_operations()
        self.blocks.clear()

    @property
    def operations(self) -> List[Operation]:
        """Flattened view of the operations in every block of this region."""
        return [op for block in self.blocks for op in block.operations]

