    #: op mnemonic, so the module symbol is exposed as ``module_name`` too.
    @property
    def sym_name(self) -> Optional[str]:
        return self.module_name

    @property
    def block(self) -> Optional[Block]:
        if not self.regions or not self.regions[0].blocks:
            return None
        return self.regions[0].blocks[0]

    @property
    def body(self) -> List[Operation]:
        """The operations in the module body, in textual order."""
        block = self.block
        return list(block.operations) if block is not None else []

    @property
    def ports(self) -> List[Port]:
        names = self.attributes.get("port_names")
        directions = self.attributes.get("port_directions")
        ftype = self.attributes.get("function_type")
        signature = ftype.value if ftype is not None else None
        if not isinstance(names, ArrayAttr) or not isinstance(directions, ArrayAttr):
            return []
        inputs = list(signature.inputs) if signature is not None else []
        outputs = list(signature.results) if signature is not None else []
        result: List[Port] = []
        in_index = out_index = 0
        for name_attr, dir_attr in zip(names, directions):
            direction = Direction.parse(dir_attr.value)
            if direction is Direction.OUTPUT:
                ptype = outputs[out_index] if out_index < len(outputs) else None
                out_index += 1
            else:
                ptype = inputs[in_index] if in_index < len(inputs) else None
                in_index += 1
            result.append(Port(name_attr.value, ptype, direction))
        return result

    @property
    def input_ports(self) -> List[Port]:
        return [p for p in self.ports if p.is_input]

    @property
    def output_ports(self) -> List[Port]:
        return [p for p in self.ports if p.is_output]

    @property
    def inout_ports(self) -> List[Port]:
        return [p for p in self.ports if p.is_inout]

    def get_port(self, name: str) -> Optional[Port]:
        for port in self.ports:
            if port.name == name:
                return port
        return None

    def total_input_bits(self) -> int:
        return sum(p.bit_width() for p in self.input_ports)

    def total_output_bits(self) -> int:
        return sum(p.bit_width() for p in self.output_ports)

    @property
    def output_op(self) -> Optional[Operation]:
        for op in reversed(self.body):
            if op.name == "hw.output":
                return op
        return None

    # -- verification -----------------------------------------------------
    def verify_signature(self) -> List[str]:
        errors: List[str] = []
        seen: set = set()
        for port in self.ports:
            if port.name in seen:
                errors.append(f"Duplicate port name: {port.name}")
            seen.add(port.name)
            if port.bit_width() == 0:
                errors.append(f"Port {port.name} has zero width")
        output = self.output_op
        expected = len(self.output_ports)
        if output is not None and output.num_operands != expected:
            errors.append(
                f"OutputOp has {output.num_operands} operands but module has "
                f"{expected} output ports"
            )
        return errors

    def verify_op(self) -> List[str]:
        errors = list(self.verify_signature())
        if self.module_name is None:
            errors.append("'hw.module' requires a 'sym_name' attribute")
        return errors


