# -- operation printing -----------------------------------------------
def _print_op(self, op: Operation) -> None:
    # Operations that are isolated from above (functions, hardware modules)
    # open a fresh SSA namespace, exactly as MLIR does, so ``%sum`` can be
    # reused in two sibling functions.
    saved_state: Optional[SSANameState] = None
    if op.has_trait(Trait.ISOLATED_FROM_ABOVE) and op.name != "builtin.module":
        saved_state = self._name_state
        self._name_state = SSANameState(preserve_names=saved_state.preserve_names)
    try:
