class OperationFolder:
    """Turns foldable operations into materialised constants.

    Constants are uniqued per block so folding a chain does not leave a trail of
    duplicate ``arith.constant`` operations.
    """

    def __init__(self, constant_op_name: str = "arith.constant") -> None:
        self.constant_op_name = constant_op_name
        self._constant_cache: Dict[Tuple[int, str, Any], Operation] = {}
        self.num_folded = 0
        self.num_constants_created = 0

    def clear(self) -> None:
        self._constant_cache.clear()

    def try_fold(self, op: Operation, rewriter: PatternRewriter) -> bool:
        """Fold ``op`` if possible.  Returns ``True`` when the IR changed."""
        if op.is_constant_like:
            return False
        if not op.num_results or not op.is_pure:
            return False
        folded = op.fold()
        if not folded or len(folded) != op.num_results:
            return False

        replacements: List[Value] = []
        for constant, result in zip(folded, op.results):
            if isinstance(constant, Value):
                replacements.append(constant)
                continue
            if not isinstance(constant, int):
                return False
            replacements.append(
                self._get_or_create_constant(constant, result.type, op, rewriter)
            )
        rewriter.replace_op(op, replacements)
        self.num_folded += 1
        return True

    def _get_or_create_constant(
        self,
        value: int,
        result_type: Type,
        anchor: Operation,
        rewriter: PatternRewriter,
    ) -> Value:
        block = anchor.parent
        key = (id(block), str(result_type), value)
        cached = self._constant_cache.get(key)
        if cached is not None and cached.parent is block:
            return cached.result(0)
        constant = rewriter.create_constant(value, result_type, before=anchor)
        self.num_constants_created += 1
        self._constant_cache[key] = constant
        return constant.result(0)


