    # ``sv.alwaysff negedge %clk`` puts the edge in ``assembly_keywords``.
    keywords = _parsed_edge_keywords(attrs)
    if clock_attr is not None:
        op.clock_edge = _normalise_edge(clock_attr.value)
    else:
        op.clock_edge = _normalise_edge(keywords[0] if keywords else None)
    if reset_attr is not None:
        op.reset_edge = _normalise_edge(reset_attr.value)
    elif len(keywords) > 1:
        op.reset_edge = _normalise_edge(keywords[1])
    elif op.num_operands > cls.RESET:
        # As in ``__init__``: a reset operand with no explicit edge is
        # sampled on its rising edge.
        op.reset_edge = "posedge"
    else:
        op.reset_edge = ""
    # Keywords are dropped when the operation is printed again, so mirror an
    # edge recovered from one into the attribute that does survive.
    if clock_attr is None and keywords:
        op.attributes.setdefault("clockEdge", StringAttr(op.clock_edge))
    if reset_attr is None and len(keywords) > 1 and op.reset_edge:
        op.attributes.setdefault("resetEdge", StringAttr(op.reset_edge))
    return op
